{
	struct pipe_inode_info *pipe = filp->private_data;
	int count, head, tail, mask;

	switch (cmd) {
		case FIONREAD:
			__pipe_lock(pipe);
			count = 0;
			head = pipe->head;
			tail = pipe->tail;
